// FUTURE @scaleflex/dam-core — folders service. See ../README.md.
//
// Browse helpers (getFolders/createFolder) mirror @scaleflex/asset-picker.
// rename/delete/move are light-dam's management layer, verified against
// js-admin-react-filerobot-v5 (src/features/folders/folders.service.ts):
// rename is `PUT /folder/{uuid}/name`; delete and move are bulk on `/folders`.
import type { DamClient } from './dam-client';
import type { Folder } from '../types/folder.types';
import type {
  GetFoldersResponse,
  RawFolder,
  ApiStatusResponse,
  CreateFolderResponse,
} from '../types/api.types';

export interface GetFoldersParams {
  folderPath?: string;
  recursive?: number;
  limit?: number;
  offset?: number;
  q?: string;
  sortBy?: 'created_at' | 'modified_at' | 'name';
  sortDirection?: 'asc' | 'desc';
}

function normalizeFolder(raw: RawFolder): Folder {
  const path = raw.path ?? raw.name;
  const parentPath = path.replace(/\/[^/]*$/, '') || '/';
  return {
    uuid: raw.uuid,
    name: raw.name.split('/').pop() || raw.name,
    path,
    parentPath,
    createdAt: raw.created_at,
    modifiedAt: raw.modified_at,
  };
}

export async function getFolders(
  client: DamClient,
  params: GetFoldersParams = {},
): Promise<Folder[]> {
  const sortField = params.sortBy ?? 'name';
  const sortDir = params.sortDirection ?? 'asc';
  const res = await client.get<GetFoldersResponse>('/folders', {
    folder: params.folderPath ?? '/',
    recursive: params.recursive ?? 0,
    limit: params.limit ?? 1000,
    offset: params.offset ?? 0,
    q: params.q,
    sort: `${sortField}:${sortDir}`,
  });
  return (res.folders ?? []).map(normalizeFolder);
}

/**
 * Create a folder. The backend's `name` is a full path; we build it from
 * parent + leaf. `parentFolderPath` is expected to start with `/`.
 */
export async function createFolder(
  client: DamClient,
  leafName: string,
  parentFolderPath: string,
): Promise<Folder> {
  const cleanParent = parentFolderPath.replace(/\/+$/, '');
  const fullPath = cleanParent ? `${cleanParent}/${leafName}` : `/${leafName}`;
  const res = await client.post<CreateFolderResponse>('/folders', { name: fullPath });
  if (res.status !== 'success' || !res.folder) throw new Error(res.msg || 'Failed to create folder');
  return normalizeFolder(res.folder);
}

// ── light-dam's management layer ─────────────────────────────────────────────

// The response also carries the updated folder (Hub's `folders.slice.ts` reads
// `response.folder` from this same endpoint), but it's discarded here — unlike
// createFolder(), every current caller (BrowseStore.renameFolderById) recomputes the
// new path itself and refetches from the server, so nothing depends on it. Return it
// if a future caller needs to update state optimistically from this response instead.
export async function renameFolder(
  client: DamClient,
  uuid: string,
  newName: string,
): Promise<void> {
  const res = await client.put<ApiStatusResponse>(`/folder/${encodeURIComponent(uuid)}/name`, {
    name: newName,
  });
  if (res?.status === 'error') throw new Error(res.msg || 'Failed to rename folder');
}

export async function deleteFolders(client: DamClient, uuids: string[]): Promise<void> {
  const res = await client.delete<ApiStatusResponse>('/folders', { folders_uuids: uuids });
  if (res?.status === 'error') throw new Error(res.msg || 'Failed to delete folders');
}

export async function moveFolders(
  client: DamClient,
  uuids: string[],
  destinationPath: string,
): Promise<void> {
  const res = await client.post<ApiStatusResponse>('/folders', {
    folders_uuids: uuids,
    new_folder_name: destinationPath,
  });
  if (res?.status === 'error') throw new Error(res.msg || 'Failed to move folders');
}
