// @scaleflex/dam-core — file-variations assembly (UI-free, pure).
//
// Turns the raw `/variants` list + the container presets + the asset itself into a
// single ordered `Variation[]` for the preview's Variations tab. Classification
// mirrors js-admin-react-filerobot-v5 / portals-fe:
//   • Original          — synthesized from the asset.
//   • Custom variants    — `/variants` rows whose name is NOT a preset and that are not bg-removed.
//   • Background-removed  — `/variants` rows with info.remove_background (kept, not preset-named).
//   • Preset variations   — one virtual row per container preset, applied as `?p=<name>`.

import type { Asset } from '../types/asset.types';
import type { Variation, Preset } from '../types/variation.types';
import type { RawVariation } from '../types/api.types';

/**
 * Apply a container preset to an original CDN URL by setting `?p=<name>` (replacing
 * any existing `p`). Returns the input unchanged if it isn't a valid URL.
 */
export function presetUrl(originalUrl: string, presetName: string): string {
  try {
    const url = new URL(originalUrl);
    url.searchParams.set('p', presetName);
    return url.toString();
  } catch {
    return originalUrl;
  }
}

/** Normalize one raw `/variants` row into a `Variation` (custom or background-removed). */
export function normalizeVariation(raw: RawVariation): Variation {
  return {
    uuid: raw.uuid,
    name: raw.name,
    url: raw.url,
    previewUrl: raw.preview ?? raw.url,
    width: raw.info?.img_w,
    height: raw.info?.img_h,
    size: raw.info?.size,
    format: raw.info?.img_type,
    isOriginal: false,
    isPreset: false,
    bgRemoved: raw.info?.remove_background === true,
  };
}

/** The Original variation, synthesized from the asset. */
function originalVariation(asset: Asset): Variation {
  return {
    uuid: asset.uuid,
    name: asset.name,
    url: asset.cdnUrl ?? '',
    previewUrl: asset.thumbnailUrl ?? asset.cdnUrl,
    width: asset.width,
    height: asset.height,
    size: asset.size,
    format: asset.fileType,
    isOriginal: true,
    isPreset: false,
    bgRemoved: false,
  };
}

/** A virtual preset variation, derived from the asset's original URL. */
function presetVariation(asset: Asset, preset: Preset): Variation {
  const base = asset.cdnUrl ?? '';
  return {
    uuid: `preset-${preset.name}`,
    name: preset.name,
    url: presetUrl(base, preset.name),
    previewUrl: presetUrl(asset.thumbnailUrl ?? base, preset.name),
    isOriginal: false,
    isPreset: true,
    bgRemoved: false,
  };
}

export interface AssembleVariationsInput {
  asset: Asset;
  /** Raw rows from `getFileVariations`. */
  variants?: RawVariation[];
  /** Container presets from `getPresets`. */
  presets?: Preset[];
}

/**
 * Assemble the full Variations list: `[Original, …custom, …background-removed, …presets]`.
 * Preset-named raw variants are excluded from the custom set (they're represented by the
 * virtual preset rows instead), matching the reference admins' behaviour.
 */
export function assembleVariations({
  asset,
  variants = [],
  presets = [],
}: AssembleVariationsInput): Variation[] {
  const presetNames = new Set(presets.map((p) => p.name));

  const custom = variants
    .filter((v) => !presetNames.has(v.name) && v.info?.remove_background !== true)
    .map(normalizeVariation);

  const bgRemoved = variants
    .filter((v) => v.info?.remove_background === true && !presetNames.has(v.name))
    .map(normalizeVariation);

  const presetRows = presets.map((p) => presetVariation(asset, p));

  return [originalVariation(asset), ...custom, ...bgRemoved, ...presetRows];
}
