import type { TFunction, TOptions } from './types';

const interpolate = (str: string, opts: Record<string, unknown>): string =>
  str.replace(/\{\{(\w+)\}\}/g, (_, k) => String(opts[k] ?? ''));

/**
 * Pass-through {@link TFunction} used before i18next has initialised (or when init failed):
 * returns the inline default with `{{placeholder}}` interpolation and count-based plural
 * selection, mirroring the i18next call shape. No i18next import, so consumers that only
 * need the fallback don't pull i18next into their module graph.
 */
export const fallbackT: TFunction = (key, defaultValueOrOptions?, options?) => {
  if (typeof defaultValueOrOptions === 'string') {
    return interpolate(defaultValueOrOptions, options ?? {});
  }
  if (typeof defaultValueOrOptions === 'object' && defaultValueOrOptions !== null) {
    const opts: TOptions = defaultValueOrOptions;
    const count = opts.count;
    if (count !== undefined) {
      const val = String(
        (count === 1 ? opts.defaultValue_one : opts.defaultValue_other) ?? opts.defaultValue ?? key,
      );
      return interpolate(val, opts);
    }
    return interpolate(String(opts.defaultValue ?? key), opts);
  }
  return key;
};
